// Prefix sources (screen ledger) and iconIds (name -> component ID).
const page=figma.root.children.find(p=>p.name==='Coqui / 17 — Prototypes & Flows');await figma.setCurrentPageAsync(page);await Promise.all(['Regular','Semi Bold','Bold'].map(style=>figma.loadFontAsync({family:'Inter',style})));
const createdNodeIds=[],mutatedNodeIds=[],frames={},labelToIcon={'Dashboard':'layout-dashboard','System Analysis':'scan-line','Hardware':'cpu','Storage':'hard-drive','Performance':'activity','Firmware & Security':'shield-check','History':'history','Settings':'settings'};
const liveSources=sources.filter(s=>s.width===1440&&s.frameId&&!s.name.includes(' / Light')).slice(0,9);
let index=0;for(const source of liveSources){const original=await figma.getNodeByIdAsync(source.frameId);const title=source.name.split(' / ')[0];const cloneName='Prototype / '+title;let root=page.children.find(n=>n.name===cloneName);if(!root){root=original.clone();page.appendChild(root);root.name=cloneName;root.x=(index%3)*1640;root.y=Math.floor(index/3)*1160;createdNodeIds.push(root.id,...root.findAll(()=>true).map(n=>n.id));}frames[title]=root;index++;}
// Keep the complete initial setup journey on the same prototype page.
const setup=frames['Set up your Mac'];const setupSteps=['Welcome','Your workload','Your preference','Privacy & scope'];
if(setup){for(let i=0;i<setupSteps.length;i++){const name='Prototype / Setup / '+setupSteps[i];let root=page.children.find(n=>n.name===name);if(!root){root=setup.clone();page.appendChild(root);root.name=name;root.x=i*1640;root.y=3600;const content=root.children.find(n=>n.name==='Workspace')?.children.find(n=>n.name==='Content');const title=content?.children.find(n=>n.type==='TEXT');if(title)title.characters=setupSteps[i];createdNodeIds.push(root.id,...root.findAll(()=>true).map(n=>n.id));}frames['Setup '+i]=root;}}
async function link(node,destination){if(!node||!destination)return;let top=node;while(top.parent&&top.parent!==page)top=top.parent;if(top.id===destination.id)return;await node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:destination.id,navigation:'NAVIGATE',transition:null,resetScrollPosition:true}]}]);mutatedNodeIds.push(node.id);}
for(const [title,root] of Object.entries(frames)){
 const side=root.children.find(n=>n.name==='Sidebar');if(side){for(const item of side.children.filter(n=>n.type==='INSTANCE')){const text=item.findAllWithCriteria({types:['TEXT']}).find(t=>labelToIcon[t.characters]);if(!text)continue;await link(item,frames[text.characters]);const icon=item.children.find(n=>n.name==='icon');const main=await figma.getNodeByIdAsync(iconIds[labelToIcon[text.characters]]);if(icon&&icon.type==='INSTANCE'&&main){icon.swapComponent(main);mutatedNodeIds.push(icon.id);}}}
 const workspace=root.children.find(n=>n.name==='Workspace');const content=workspace?.children.find(n=>n.name==='Content');if(!content)continue;const buttons=content.children.filter(n=>n.type==='INSTANCE'&&n.findAllWithCriteria({types:['TEXT']}).some(t=>['Analyze System','Analyze storage','Start analysis','Explore first','Review coverage','Inspect evidence','Open Login Items','System Settings','Inspect report','Review local data'].includes(t.characters)));
 for(const button of buttons){const copy=button.findAllWithCriteria({types:['TEXT']})[0]?.characters;let target=title.startsWith('Setup ')?frames[Number(title.slice(6))<3?'Setup '+(Number(title.slice(6))+1):'System Analysis']:copy==='Explore first'?frames.Dashboard:copy==='Analyze storage'?frames.Storage:copy==='Review local data'?frames.Settings:frames['System Analysis'];await link(button,target);}
}
const flowStarts=[{nodeId:frames['Setup 0']?.id,name:'A — First analysis'},{nodeId:frames.Dashboard?.id,name:'Read-only workspace'},{nodeId:frames.Storage?.id,name:'C — Storage inspection (Phase 1)'}].filter(f=>f.nodeId);page.flowStartingPoints=flowStarts;
return{createdNodeIds,mutatedNodeIds,frames:Object.fromEntries(Object.entries(frames).map(([k,v])=>[k,v.id])),flowStarts,prototypePageId:page.id};
